from functools import partial

# Step 6: Define a function to check if a propositional formula evaluates to True for a given interpretation.
def check(f, s):
    if f.is_literal():
        return f in s
    elif f.is_and():
        return all((check(e, s) for e in f.args))
    elif f.is_or():
        return any((check(e, s) for e in f.args))
    elif f.is_not():
        return not check(f.args[0], s)

# Step 7: Define a function to extract the literals from a propositional formula.
def get_name(f):
    if f.is_literal():
        yield f
    else:
        yield from chain.from_iterable(map(get_name, f.args))

