def validate_base(base):
    try:
        base = int(base)
        if base < 2 or base > 36:
            raise ValueError
    except ValueError:
        print("Invalid base! Please enter a positive integer between 2 and 36.")
        return False
    return True

def validate_string(string, base):
    valid_digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for digit in string:
        if digit.upper() not in valid_digits[:base]:
            print("Invalid string! The string contains an invalid digit for the specified base.")
            return False
    return True

def convert_base(string, current_base, desired_base):
    converted_number = 0
    power = 0

    for digit in string[::-1]:
        value = int(digit, current_base)
        converted_number += value * (current_base ** power)
        power += 1

    return converted_number

