public class Palindrome {

 public static boolean isPalindrome(int[] array) {
  // Check for null or empty
  if (array == null || array.length == 0) {
   return false;
  }

  for (int i = 0, j = array.length - 1; i < array.length; i++, j--) {
   if (array[i] != array[j]) {
    return false;
   }
  }
  return true;
 }

