Here is an implementation of the DateComparator class in C++:

```cpp
#include <iostream>
#include <sstream>
#include <stdexcept>

using namespace std;

class DateComparator {
private:
    int month1, day1, year1;
    int month2, day2, year2;

    bool isLeapYear(int year) {
        if (year % 4 == 0) {
            if (year % 100 == 0) {
                if (year % 400 == 0) {
                    return true;
                } else {
                    return false;
                }
            } else {
                return true;
            }
        } else {
            return false;
        }
    }

    int getDaysInMonth(int month, int year) {
        switch (month) {
            case 2:
                return isLeapYear(year) ? 29 : 28;
            case 4:
            case 6:
            case 9:
            case 11:
                return 30;
            default:
                return 31;
        }
    }

    int getDayOfYear(int month, int day, int year) {
        int days = 0;
        for (int i = 1; i < month; i++) {
            days += getDaysInMonth(i, year);
        }
        days += day;
        return days;
    }

public:
    DateComparator(const string& date1, const string& date2) {
        stringstream ss1(date1), ss2(date2);
        char discard;

        ss1 >> month1 >> discard >> day1 >> discard >> year1;
        ss2 >> month2 >> discard >> day2 >> discard >> year2;

        if (ss1.fail() || ss2.fail()) {
            throw invalid_argument("Invalid date format.");
        }
    }

    int compareDates() {
        int days1 = getDayOfYear(month1, day1, year1);
        int days2 = getDayOfYear(month2, day2, year2);

        int days = 0;
        if (year2 > year1) {
            for (int year = year1 + 1; year < year2; year++) {
                days += isLeapYear(year) ? 366 : 365;
            }
            days += getDaysInMonth(month1, year1) - day1;
            days += days2;
        } else if (year2 < year1) {
            for (int year = year2 + 1; year < year1; year++) {
                days += isLeapYear(year) ? 366 : 365;
            }
            days += getDaysInMonth(month2, year2) - day2;
            days += days1;
        } else {
            days = days2 - days1;
        }

        return days;
    }
};

int main() {
    try {
        DateComparator dateComp("10/10/2020", "10/11/2020");
        int daysBetween = dateComp.compareDates();
        cout << "Number of days between the two dates: " << daysBetween << endl;
    } catch (const exception& e) {
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}
```

This implementation includes a private helper function `isLeapYear()` to check if a year is a leap year, and `getDaysInMonth()` to get the number of days in a given month of a given year. The `compareDates()` method calculates the number of days between the two dates by iterating through the years, considering leap years and the number of days in each month. An exception is thrown if the input date format is invalid.

In the main function, an instance of the DateComparator class is created with two date strings "10/10/2020" and "10/11/2020". The `compareDates()` method is called to get the number of days between the two dates, which is then printed to the console.

