using namespace std;

void reverseArray(int arr[], int n)  
{  
    int i, temp;  
    for (i = 0; i < n / 2; i++)  
    {  
        temp = arr[i];  
        arr[i] = arr[n - i - 1];  
        arr[n - i - 1] = temp;  
    }  
}  

int main()  
{  
    int arr[] = { 1, 2, 3, 4, 5, 6};  
    int n = sizeof(arr) / sizeof(arr[0]);  

    // Function calling  
