```c++
#include <iostream>
using namespace std;
int factorial(int n) {
    if (n < 0) {
        cout << "Error: Input number must be positive." << endl;
        return -1;
    }
    else if (n == 0) {
        return 1;
    }
    else {
        return n * factorial(n-1);
    }
}
int main() {
    int num;
    cout << "Enter a positive integer: ";
    cin >> num;
    int result = factorial(num);
    if (result != -1) {
        cout << "Factorial of " << num << " is " << result << endl;
    }
    return 0;
}
```
The `factorial` function takes an integer `n` as input and returns the factorial of `n`. The function first checks if `n` is negative. If it is, an error message is printed and `-1` is returned. If `n` is 0, the function returns 1 (since 0! = 1). Otherwise, the function multiplies `n` with the factorial of `n-1` (which is calculated using recursion).
