class Solution:
    def firstRep(self, s):
        # Step 7: Initialize an ordered dictionary to keep track of the frequency of each character.

        g = OrderedDict()
        # Step 8: Iterate through the characters of the string and update the frequency in the ordered dictionary.

        for i in range(0, len(s)):
            c = s[i]
            if c not in g:
                g[c] = 1
            else:
